def expand(encounters):
    for row in encounters:
        row.update(id=row["name"].lower().replace(" ","_"),agility=26 if "interceptor" in row["name"] else 10,shield_resistance=0,preparation_seconds=3 if row["name"]=="Fleet objective" else 2 if row["name"] in ["Advanced bomber","Electronic raider"] else 0,ammunition="heavy_missile" if row["name"]=="Advanced bomber" else None,ammunition_per_weapon=20 if row["name"]=="Advanced bomber" else 0,exposed_seconds=8 if row["name"] in ["Electronic raider","Elite heavy target","Fleet objective"] else 0,bulk_reserve=72 if row["name"]=="Fleet objective" else 36 if row["gunnery"]>=35 else 18,component_attempts=6 if row["name"]=="Fleet objective" else 3 if row["gunnery"]>=35 else 2)
    return [dict(row,profile=next(e["id"] for e in encounters if e["name"]==row["profile"])) for row in BINDINGS]
